// Content models parsed from assets/data/content.json (generated by scripts/generate-content.ts).

List<String> _strings(dynamic v) =>
    (v as List? ?? const []).map((e) => e.toString()).toList();

/// A coach line spoken [t] seconds into a step's practice (web `StepCue`).
class StepCue {
  final int t;
  final String l;
  const StepCue(this.t, this.l);
  factory StepCue.fromJson(Map<String, dynamic> j) =>
      StepCue((j['t'] as num).toInt(), j['l'] as String);
}

/// Celebrated on a card right after a step (web `StepUnlock`): a learned form ([n] of 24),
/// a skill or a linked sequence.
class StepUnlock {
  final String k, t, l;
  final int? n;
  const StepUnlock(this.k, this.t, this.l, [this.n]);
  factory StepUnlock.fromJson(Map<String, dynamic> j) => StepUnlock(
    j['k'] as String? ?? 'skill',
    j['t'] as String? ?? '',
    j['l'] as String? ?? '',
    (j['n'] as num?)?.toInt(),
  );
}

/// Teaching level of a new skill (1 = learn it slowly, 2 = with the breath).
class StepLevel {
  final int n;
  final String l;
  const StepLevel(this.n, this.l);
}

class SessionItem {
  final String e;
  final int s;

  /// Lesson phase label ("Warm-up", "New today", …) — authored courses only.
  final String? p;

  /// Authored lesson-specific practice cue; older content omits it.
  final String? g;

  /// Title override (e.g. "Find your root" on the stance film).
  final String? t;
  final StepLevel? lv;

  /// "Watch first" demo seconds before the practice; 0 = straight in; null = legacy step (rest before it).
  final int? w;

  /// Spoken during the demo (what to watch for) and as the practice starts.
  final String? wl, go;

  /// Timed practice cues (replace the step-by-step instructions).
  final List<StepCue> c;

  /// Dedicated lesson film key (`lf-*`) shown instead of the movement's demo.
  final String? f;
  final StepUnlock? u;
  const SessionItem(
    this.e,
    this.s, [
    this.p,
    this.g,
    this.t,
    this.lv,
    this.w,
    this.wl,
    this.go,
    this.c = const [],
    this.f,
    this.u,
  ]);
  factory SessionItem.fromJson(Map<String, dynamic> j) {
    final lv = j['lv'] as Map?;
    final u = j['u'] as Map?;
    return SessionItem(
      j['e'] as String,
      (j['s'] as num).toInt(),
      j['p'] as String?,
      j['g'] as String?,
      j['t'] as String?,
      lv == null
          ? null
          : StepLevel((lv['n'] as num?)?.toInt() ?? 1, lv['l'] as String? ?? ''),
      (j['w'] as num?)?.toInt(),
      j['wl'] as String?,
      j['go'] as String?,
      [
        for (final x in (j['c'] as List? ?? const []))
          StepCue.fromJson(x as Map<String, dynamic>),
      ],
      j['f'] as String?,
      u == null ? null : StepUnlock.fromJson(u.cast<String, dynamic>()),
    );
  }
}

List<SessionItem> _items(dynamic v) => (v as List)
    .map((e) => SessionItem.fromJson(e as Map<String, dynamic>))
    .toList();

/// The tutor's welcome / congratulations film around a guided lesson, one spoken caption per line.
class LessonTutor {
  final String film;
  final List<String> lines;
  const LessonTutor(this.film, this.lines);
  static LessonTutor? fromJson(dynamic j) => j is Map
      ? LessonTutor(j['film'] as String? ?? '', _strings(j['lines']))
      : null;
}

class Exercise {
  final String id,
      name,
      category,
      kind,
      image,
      level,
      equipment,
      description,
      breath,
      cue;
  final int durationSec;
  final double kcalPerMin;
  final List<String> focus, steps, benefits;

  /// Optional licensed media (video loop / narrated guidance). Empty until provided.
  final String? video, audio;

  /// Key of our bundled demo film (`assets/video/<demo>.mp4`), or null.
  final String? demo;
  final String? tip;
  bool get isAffirmation => kind == 'affirmation';

  /// Looping demo film: licensed network media first, then our bundled demo asset.
  ({String src, bool asset})? get film => video != null
      ? (src: video!, asset: false)
      : (demo != null ? (src: 'assets/video/$demo.mp4', asset: true) : null);
  Exercise.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      name = j['name'],
      category = j['category'],
      kind = j['kind'] ?? 'move',
      video = (j['media'] as Map?)?['video'] as String?,
      audio = (j['media'] as Map?)?['audio'] as String?,
      demo = j['demo'] as String?,
      tip = j['tip'] as String?,
      image = j['image'],
      level = j['level'],
      equipment = j['equipment'],
      description = j['description'],
      breath = j['breath'],
      cue = j['cue'],
      durationSec = (j['durationSec'] as num).toInt(),
      kcalPerMin = (j['kcalPerMin'] as num).toDouble(),
      focus = _strings(j['focus']),
      steps = _strings(j['steps']),
      benefits = _strings(j['benefits']);
}

class Category {
  final String id, name, tagline, description, image;
