      description = j['description'],
      image = j['image'],
      exerciseIds = _strings(j['exerciseIds']),
      signatureMinutes = (j['signatureMinutes'] as num).toInt(),
      items = _items(j['session']['items']),
      kcal = (j['session']['kcal'] as num).toInt();
}

