class PlanDay {
  final int day;
  final String title;
  final bool restore;
  final List<String> focus;
  final List<SessionItem> items;
  final int kcal;
  final LessonTutor? intro, outro;

  /// Ask "how calm do you feel?" before and after the lesson.
  final bool check;
  PlanDay.fromJson(Map<String, dynamic> j)
    : day = (j['day'] as num).toInt(),
      title = j['title'],
      restore = j['restore'] as bool,
      focus = _strings(j['focus']),
      items = _items(j['items']),
      kcal = (j['kcal'] as num).toInt(),
      intro = LessonTutor.fromJson(j['intro']),
      outro = LessonTutor.fromJson(j['outro']),
      check = j['check'] as bool? ?? false;
}

class Plan {
  final String id,
      title,
      subtitle,
      description,
      image,
      group,
      level,
      equipment,
      kind;
  final int minutesPerDay;

  /// Premium programs open only their first [freeDays] days without TaiChi Flow Plus.
  final bool premium;
  final int freeDays;
  final List<String> benefits;
  final List<PlanDay> days;

  /// Coach voice of this course's lessons (e.g. `master` for Master Wei); null = the app coach.
  final String? voice;
  bool get isSingleSession => days.length == 1;
  Plan.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      voice = j['voice'] as String?,
      kind = j['kind'] ?? 'challenge',
      premium = j['premium'] as bool? ?? false,
      freeDays = (j['freeDays'] as num? ?? 0).toInt(),
      title = j['title'],
      subtitle = j['subtitle'],
      description = j['description'],
      image = j['image'],
      group = j['group'],
      level = j['level'],
      equipment = j['equipment'],
      minutesPerDay = (j['minutesPerDay'] as num).toInt(),
      benefits = _strings(j['benefits']),
      days = (j['days'] as List)
          .map((e) => PlanDay.fromJson(e as Map<String, dynamic>))
          .toList();
}

class ScriptLine {
  final int t;
  final String text;

  /// Length of this line's voice clip in seconds (0 in content from before timed narration).
  final double d;
  const ScriptLine(this.t, this.text, [this.d = 0]);
  ScriptLine.fromJson(Map<String, dynamic> j)
    : t = (j['t'] as num).toInt(),
      text = j['text'],
      d = (j['d'] as num?)?.toDouble() ?? 0;
}

/// A round of [n] whole breath cycles starting [t] seconds into a breath meditation.
class BreathRound {
  final int t, n;
  const BreathRound(this.t, this.n);
  BreathRound.fromJson(Map<String, dynamic> j)
    : t = (j['t'] as num).toInt(),
      n = (j['n'] as num).toInt();
}

class Meditation {
  final String id, title, subtitle, category, image, track, theme;

  /// Zen music this meditation plays (content before the music list only had [track]).
  final String music;
  final int minutes;
  final bool premium;
  final List<int>? breath;
  final List<ScriptLine> script;

  /// Breath rounds of a breath meditation (null for other meditations and older content).
  final List<BreathRound>? rounds;
  Meditation.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      title = j['title'],
      subtitle = j['subtitle'],
      category = j['category'],
      image = j['image'],
      track = j['track'],
      music = (j['music'] as String?) ?? j['track'],
      rounds = (j['rounds'] as List?)
          ?.map((e) => BreathRound.fromJson(e as Map<String, dynamic>))
          .toList(),
      theme = j['theme'],
      minutes = (j['minutes'] as num).toInt(),
      premium = j['premium'] as bool,
      breath = j['breath'] == null
          ? null
          : (j['breath'] as List).map((e) => (e as num).toInt()).toList(),
      script = (j['script'] as List)
          .map((e) => ScriptLine.fromJson(e as Map<String, dynamic>))
          .toList();
}

